Method.Implementation:
#dim tSC As %Status 
 set tSC = $$$OK
 Set comment = ""
 set clsDeployCmt = ""
 set compNm = $ZSTRIP(compNm,"*W")
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "In DeployFile, deploy " _compNm _ " type: " _  deployType)

 set ..DeployDirectory = $$$USRRELEASEBASEDIR _ usrNm _ $$$SVNSRCTRUNK
 set ..DeployLogDirectory = $$$USRRELEASEBASEDIR _  usrNm _ $$$LOGDIR

 Set tProductionClassIncluded = 0
 NEW $NAMESPACE
 try {
 	set $NAMESPACE = nmSp
 } catch err
 {
	 return "Invalid namespace: " _ nmSp _ err.Name _ " " _ err.Code
 }
 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "NAMESPACE: " _ $NAMESPACE )
 set tProductionName = ##class(Ens.Director).GetActiveProductionName()

 if tProductionName = ""
 {
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not get active production in " _ $NAMESPACE)
  return "Could not get active production in " _ $NAMESPACE
 }
 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Active PROD: " _ tProductionName)

  set tSC = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).DoSvnSetup(usrNm, passwd)
 if $$$ISERR( tSC )
 {
	 return "ERROR in SVN: " _ tSC
 }
 set deployComp = ""

 IF ' ##class(%File).DirectoryExists(..DeployLogDirectory)
 {
   Do ##class(%File).CreateDirectory(..DeployLogDirectory)
 }
 set deployType = $ZSTRIP($ZCVT(deployType, "U"), "<>W")

 if ( (deployType = "NEW") || (deployType = "UPDATE" && depCls = 1))
 {
 	Set fileName = ..DeployDirectory_"Deployment_CLS_" _compNm_".xml"
 	set tSC = ..CheckoutFile(compNm, fileName, usrNm, passwd, rev )

 }

 if $$$ISERR(tSC)
 {
	 // Class file not found
   		if (deployType = "NEW" )
   		{
	   		// Deploy config file
	 		set tSC = $$$OK
	   		// Information to indicate for NEW deployment
		 	Set clsDeployCmt =  " Class file not found for the component. (Applicable for Processes) " _ fileName _ " <BR>" 

   		}
   		elseif (deployType = "UPDATE" && depCls = 1) 
   		{
	   		// Information to indicate for NEW deployment
	 		Set comment = "Class file not found for the component: " _ fileName
   		}
 }
 else
 {
    if ( (deployType = "NEW") || (deployType = "UPDATE" && depCls = 1))
 	{
 		try {
	   		set tSC = ..DeployClassFiles(compNm, fileName, rev, nmSp, tProductionName, usrNm, passwd, env)
 		} catch err
 		{
	 		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exception in DeployClassFiles")
	 		set tSC = $$$ERROR("Exception in DeployClassFiles")
 		}
 		if $$$ISERR(tSC)
 		{
			Set comment =  ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, "DeployClassFiles failed: " )
 		}
 		else
 		{
	 		set clsDeployCmt = " Successfully deployed the classes. "
 		}
 		Set comment = comment _ "; View LOG and ROLLBACK files  for " _ compNm _ " in " _ ..DeployLogDirectory _ "<BR>"
 	}
 }

 // Deploy component - after class file is done
 if $$$ISOK(tSC)
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Deploy Config file")
   if ( (deployType = "NEW") || ( (deployType = "UPDATE") && ((depConf = 1) || (changeCls = 1)) ) )
   {
	 Set fileName = ..DeployDirectory_"Deployment_CONFIG_" _compNm_".xml"

 	 set tSC = ..CheckoutFile(compNm, fileName, usrNm, passwd, rev )

 	 if $$$ISERR(tSC)
 	 {
	 	Set comment = comment _ ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, " CONFIG File not found, checkout failed. " _ tSC)
	 	return comment
 	 }
 	 if ( (deployType = "UPDATE") && (changeCls = 1))
 	 {
	 	 try {
		   set tSC = ..ChangeComponentClass(compNm, fileName, rev, nmSp, tProductionName, usrNm, passwd, env, deployType)
	 	 } catch err
	 	 {
		 	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exception in ChangeComponentClass")
		 	 set tSC = $$$ERROR("Exception in ChangeComponentClass")
	 	 }

 	 }
 	 else
 	 {

	 	 try {
		   set tSC = ..DeployComponent(compNm, fileName, rev, nmSp, tProductionName, usrNm, passwd, env, deployType)
	 	 } catch err
	 	 {
		 	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exception in DeployComponent")
		 	 set tSC = $$$ERROR("Exception in DeployComponent")
	 	 }
 	 }
	 if $$$ISERR(tSC)
	 {
		Set comment = comment _ ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, " CONFIG DeployComponent failed: ")
		Set comment = comment _ "; View LOG and ROLLBACK files  for " _ compNm _ " in " _ ..DeployLogDirectory  _ "<BR>"
	 }
	 else
	 {
		 // SUCCESS
		 if (clsDeployCmt '= "")
		 {
			 Set comment = ""
		 }
		Set comment = comment _ "Successfully deployed " _ compNm _ "<BR>"
		Set comment = comment _ "; View LOG and ROLLBACK files  for " _ compNm _ " in " _ ..DeployLogDirectory  _ "<BR>"
		if (clsDeployCmt '= "")
		 {
			 Set comment = comment _ clsDeployCmt  _ "<BR>"
		 }
	 }
   }
   else
   {
	   Set comment =  clsDeployCmt  _ comment _ "<BR>"
   }
 }


 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exit DeployFile: " _ compNm _", " _ rev _", " _ "Status: " _ comment)
 return comment


#dim tSC As %Status 
 set tSC = $$$OK
 Set details = "The results of deployment(s) are logged into " _ fNm _ ".log"
 set deployType = "NEW"

 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "In DeployFiles, deploy: " _fNm)
 set oldID = $IO
 // DeployCode line generates output to console; causes javascript to throw error
 OPEN "/dev/null/" 
 USE "/dev/null/"
 if (##class(%File).Exists(fNm) )
	{
	   try {
         Set fileObj=##class(%Library.File).%New(fNm)
         Do fileObj.Open("RS") ; Read mode and as stream
         Set origNmSp =  $NAMESPACE

         Set wFileObj=##class(%Library.File).%New(fNm _ ".log")
         Do wFileObj.Open("WN") ; WRITE mode
         While 'fileObj.AtEnd 
         {
	        set fLn = fileObj.ReadLine(,.sc,.eol)
	        WRITE !, fLn
	        if ($E(fLn, 1) = "#")
	        {
		        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Comment line: " _ fLn)
	        }
	        else
	        {
		        SET flds=$LENGTH(fLn,",")

		        if (flds = 3)
		        {
			        try {
	        			set compNm = $ZSTRIP($PIECE(fLn, ",", 1),"<>WC")
	        			set nmSp = $ZSTRIP($PIECE(fLn, ",", 2),"<>WC")	        			
	        			set revNum = $ZSTRIP($PIECE(fLn, ",", 3),"<>WC")
	        			if ($ISVALIDNUM(revNum))
	        			{
		        			Set $NAMESPACE = nmSp
		        			do wFileObj.WriteLine(fLn)
		        			set stat = ..ValidateSvnRevision(compNm, usrNm, passwd, revNum )
							if $$$ISOK(stat)
							{
   		       			 		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  "Deploy " _ compNm _ " in NAMESPACE: " _ $NAMESPACE )
   		       			 		set cmt = ..DeployFile(compNm, deployType, nmSp , usrNm, passwd, revNum, env, 0, 0, 0 )

								do wFileObj.WriteLine(cmt)
								do wFileObj.WriteLine("----")
							}
							else
							{
								do wFileObj.WriteLine("SVN Revision: " _ revNum _ " is not valid, " _ stat)
								do wFileObj.WriteLine("----")
							}
	        			}


			        } catch e
			        {
				        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Invalid namespace: " _ nmSp)
			        }
			        Set $NAMESPACE = origNmSp			        
		        }
	        }
         }
         Do fileObj.Close()
         do wFileObj.Close()

 	     Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exit DeployFiles: " _ details)
 	   } catch e
	        {
		        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exception in DeployFiles " _ e)
	        }
	}
	else
	{
		set details = "Could not open file: " _ fNm
	}
	CLOSE "/dev/null/"

 	OPEN oldID
 	USE oldID

 	return tSC

#dim tSC As %Status = $$$OK
 if (compNm '[ "||") 
 {
  set ItemByConfigName = tProductionName_"||"_compNm
 }
 else
 {
	 set ItemByConfigName = compNm
 }

 Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(ItemByConfigName)
 If $IsObject(tItem)
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, ItemByConfigName _ " already exists") 

	 if (deployType = "NEW")
	 {
		 Quit $$$ERROR($$$GeneralError, ItemByConfigName _ " already exists")
	 }
 }

 set parseFl = ##class(IHC.ITF.SrcCtrlPkg.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(fileName, compNm)

 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "After parse " _ tSC _", " _ parseFl.IsItfExportFile() _ " / " _ parseFl.IsConfigFile() )

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) && (parseFl.IsConfigFile()) )
  {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "After parse, compare: " _ $ZCVT(parseFl.itemsInfo.GetAt(1).itemName, "U") _ " = " _ $ZCVT(compNm, "U") )
	 if ($ZCVT(parseFl.itemsInfo.GetAt(1).itemName, "U") = $ZCVT(compNm, "U") )
	 {
 		set tSC = ..Deploy(compNm, fileName, "Config", tProductionName, usrNm)
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		set dt = $ZDATETIME($HOROLOG,3, 1)
	 		set tSC = ..updateImpl(usrNm, passwd, compNm, nmSp, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env, dt)
 		}
	 }
	 else
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "DeployComponent File does not have config for " _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Parsing the file failed " _ tSC)
	 Quit $$$ERROR($$$GeneralError, "Parsing the file failed " _ tSC _ " for " _ compNm)
  }
  return tSC

#dim tSC As %Status = $$$OK
 if (compNm '[ "||") 
 {
  set ItemByConfigName = tProductionName_"||"_compNm
 }
 else
 {
	 set ItemByConfigName = compNm
 }

 Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(ItemByConfigName)
 If $IsObject(tItem)
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, ItemByConfigName _ " already exists") 

	 if (deployType = "NEW")
	 {
		 Quit $$$ERROR($$$GeneralError, ItemByConfigName _ " already exists")
	 }
 }

 set parseFl = ##class(IHC.ITF.SrcCtrlPkg.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(fileName, compNm)



 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) && (parseFl.IsConfigFile()) )
  {
	 if ($ZCVT(parseFl.itemsInfo.GetAt(1).itemName, "U") = $ZCVT(compNm, "U") )
	 {

 		Set tProductionName = ##class(Ens.Director).GetActiveProductionName()


   		Set item = ##class(Ens.Config.Production).OpenItemByConfigName(compNm)
 		If $IsObject(item)
 		{				

				Set production = item.Production
				set pClassName = parseFl.GetClass()
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Item: " _ item _ ", " _ item.Production _ ", Exisiting Class: " _ item.ClassName _ ", New class: " _ pClassName)


				// Set the new classname
				Set item.ClassName = pClassName

				// Remove settings that do not belong in the new class/adapter
				Set settings = item.Settings

				Set modified = 0
				set getSet = "GetClassSettings: " _ pClassName
				Try {

					Do $ClassMethod(pClassName,"GetSettings",.tClassSettings)
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  "Adapter: " _ item.AdapterClassName())

					If (item.AdapterClassName()'="") 
					{
						set getSet = "GetAdapterSettings " _ item.AdapterClassName()
						Do $ClassMethod(item.AdapterClassName(),"GetSettings",.tAdapterSettings)
					}
				} Catch {
					set tSC = $$$ERROR(" Error in getting setting: " _ getSet)
				}
				If ($$$ISOK(tSC)) {
					For i = 1:1 {
						Quit:i>settings.Count()
						Set sett = settings.GetAt(i)
						Set type = sett.Target
						Set name = sett.Name
						Set val = sett.Value
						// WRITE !, sett _", " _ type _ ", " _ name _ ", " _ val
						Set remove = 1
						Try {
							If type="Host" {
								Set tSC = $ClassMethod(pClassName, name_"IsValid", val)
								Set remove = $S($$$ISERR(tSC):1,1:'$D(tClassSettings(":",name)))
							}
							ElseIf type="Adapter" {
								Set tSC = $ClassMethod(item.AdapterClassName(), name_"IsValid", val)
								Set remove = $S($$$ISERR(tSC):1,1:'$D(tAdapterSettings(":",name)))
							}
						}
						Catch {
							set tSC = $$$ERROR(" Error in finding class settings")

						}
						If remove {

							Do settings.RemoveAt(i)
							Set i = i-1
							Set modified = 1
						}
					}
					If ( ($$$ISOK(tSC)) && modified) {
						Set item.Settings = settings
					}
				}
				If ($$$ISOK(tSC)) {

					// Save and update the Production's XData block
					Set tSC = item.%Save()
					If ($$$ISOK(tSC)) {
						Set tSC = production.SaveToClass(item)
					}
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Save and updated class " _ tSC)
				}
	 		}
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		set dt = $ZDATETIME($HOROLOG,3, 1)
	 		set tSC = ..updateImpl(usrNm, passwd, compNm, nmSp, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env, dt)
 		}
	 }
	 else
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "ChangeComponentClass File does not have config for " _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "ChangeComponentClass File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Parsing the file failed " _ tSC)
	 Quit $$$ERROR($$$GeneralError, "Parsing the file failed " _ tSC _ " for " _ compNm)
  }
  return tSC

	set tSC = $$$OK

	try {

		 	NEW $NAMESPACE
     		set $NAMESPACE = "ITFCOMMON"
	 		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
	 		set depCl.Username = %session.Data("srcHistUsrNm")
		 	set depCl.Password = %session.Data("srcHistPsWd")
		 	Set depCl.Location = ..WSLocation
		 	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "updateImpl Call " _ depCl.Location)
	 		set tSC = depCl.UpdateComponentImpl(compNm, nmSp, fileName, rev, fileInfo, env, dt, usrNm)
	 		return tSC
	} catch err
	{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in updating Component in DB: " _ depCl.SoapFault.Reason.Text)
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	}

	return tSC

	set tSC = $$$OK

	try {

		 	NEW $NAMESPACE
     		set $NAMESPACE = "ITFCOMMON"
	 		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
	 		set depCl.Username = %session.Data("srcHistUsrNm")
		 	set depCl.Password = %session.Data("srcHistPsWd")
		 	Set depCl.Location = ..WSLocation
		 	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "updateClass Call " _ depCl.Location)
	 		set tSC = depCl.UpdateClassItem(clNm , componentNm , nmSp, DeploymentFile, fileVersion, fileInfo, env, dt, usrNm)

	 		return tSC
	} catch err
	{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in Web service: "  _ depCl.SoapFault.Reason.Text)
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	}

	return tSC

#dim tSC As %Status = $$$OK
 set parseFl = ##class(IHC.ITF.SrcCtrlPkg.parseXmlFile).%New()

 set tSC = parseFl.ParseFile(fileName, compNm)

 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "DeployClassFiles " _ parseFl.IsItfExportFile())

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) )
  {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "DeployClassFiles " _  parseFl.itemsInfo.Count())

	 if (parseFl.itemsInfo.Count() < 1)
	 {
		  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "DeployClassFiles File does not have config for any class in file" _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for any class in file " _ compNm)
	 }


	 if ($ZCVT(parseFl.itemsInfo.GetAt(1).itemName, "U") = $ZCVT(compNm, "U") )
	 {
 		set tSC = ..Deploy(compNm, fileName, "Class", tProductionName, usrNm)
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		try {
		 		set dt = $ZDATETIME($HOROLOG,3, 1)

	 		 set tSC = ..updateImpl(usrNm, passwd, compNm, nmSp, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env, dt)
	 		// Update Database for each class
	 		FOR ind=1:1:parseFl.itemsInfo.Count()
	 		{
		 	   set tSC = ..updateClass(usrNm, passwd, parseFl.itemsInfo.GetAt(ind).itemName, compNm, nmSp, fileName, 
	 		   parseFl.itemsInfo.GetAt(ind).versionNum, parseFl.itemsInfo.GetAt(ind).itemInfo, env, dt)
	 		   if $$$ISERR(tSC)
	 		   {
		 		   Return tSC
	 		   }
	 		}
	 		} catch err
	 		{

                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, $ZERROR)

            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)

	 		}
 		}
 		else
 		{
	 		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Error in DeployClassFiles")
 		}
	 }
	 else
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "DeployClassFiles File does not have config for " _ compNm)
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Parsing the file failed ")
  	 Quit $$$ERROR($$$GeneralError, "Parsing the file failed ")
  }
  Quit tSC

set CreateRollback = 1 set tTime = $Replace($ZDATETIME($H, 3), " ", "_") SET RollbackFilename = ..DeployLogDirectory_"Deployment_" _ compNm _ "_" _ type _ "_ROLLBACK_"_tTime Do ##class(%File).Delete(RollbackFilename)
SET WhereToLog = "L" SET LogFile = ..DeployLogDirectory_"Deployment_" _ compNm _ "_" _ type _ "_LOG_"_tTime Do ##class(%File).Delete(LogFile) try { set oldID = $IO // DeployCode line generates output to console; causes javascript to throw error OPEN "/dev/null/" USE "/dev/null/"
// set pAllowDeployToSource As %Boolean = 1 to allow re-deploy
Set tSC = ##class(Ens.Deployment.Deploy).DeployCode(DeploymentFile,tProductionName,CreateRollback,RollbackFilename,WhereToLog,LogFile, 1)
CLOSE "/dev/null/"
OPEN oldID USE oldID Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Deploy status: " _ $case(tSC, 1:" OK",:"Error") ) Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "For details, view " _ LogFile) IF ($$$ISERR(tSC)) { set cmt = ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, " (Ens.Deployment.Deploy).DeployCode failed: ") set tSC = $$$ERROR( cmt) }
} catch err { Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Exception in DeployCode, view " _ LogFile) set tSC = err.AsStatus() } Quit tSC


	set tSC = $$$OK
	if (rev '= "")
	{

		Do ##class(%File).Delete(fileNm)
		Set cmd= $$$SVNUPDATE _ " --revision " _ rev
		Set cmd= cmd _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _  fileNm 

		Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd(cmd)
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, $$$SVNUPDATE _ ", user: " _ usrNm _ ", file: " _ fileNm _ ", rev:" _ rev _ " , status: " _ status)
		if (status '= 0)
		{
			set tSC = $$$ERROR($$$GeneralError, $$$SVNUPDATE _ " --revision " _ rev _ " failed")
		}
		if ##class(%File).Exists(fileNm)
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out by SVNUPDATE " _ fileNm _ ", version: " _ rev)
		}
		else {
			Set cmd= $$$SVNCHECKOUT _ " --revision " _ rev
		    Set cmd= cmd _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _  fileNm 

		    Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd(cmd)
		    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, $$$SVNCHECKOUT _ ", file: " _ fileNm _ ", rev:" _ rev _ " , status: " _ status)

		    if ##class(%File).Exists(fileNm)
		    {
			    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out " _ fileNm _ ", version: " _ rev)
		    }
		    else {
  			   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not checkout file " _ fileNm)
  			   set tSC = $$$ERROR($$$GeneralError, "Could not checkout file " _ fileNm)
		    }
 		}
	}
	else
	{		
		  set tSC = $$$ERROR($$$GeneralError, "Checkout: Revision number is required") 
	}

 	Quit tSC

	set tSC = $$$OK
	set infoSearchStr = "LastChangedRev:"
	set logSearchStr = "r" _ rev _ "|"
	set fileType = "CLS"


	set createDeployCls = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentFiles).%New()
	for ind=0:1:1
	{ 
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "ValidateSvnRevision: Rev # " _ rev _ ", for " _ ind)
		//check revision for class and config file
		set retStr = createDeployCls.GetVersions(compNm, usrNm, passwd, ind)
	/***
	 Set file=##class(%File).%New("/tmp/GetVersions" _ compNm _ $ZH _ ".txt")	
	Do file.Open("WN")
	Do file.WriteLine(retStr)
	Do file.Close()
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "ValidateSvnRevision: created file")
 	***/

		// SVN infor and log line will be returned
		// Info line: Last Changed Rev: 2274
		// Log line: r2223 | cbelde | 2016-07-12 16:15:18 -0600 (Tue, 12 Jul 2016) | 25 lines

		if ($L(retStr) <= 0)
		{
			if ( ind = 1)
			{
				//Config not found
				set tSC = $$$ERROR($$$GeneralError, "Could not get config file with SVN revision for : " _ compNm)
				Quit 
			}
		}
		else
		{
			if ( ind = 1)
			{
				SET fileType = "CONFIG"
			}
			set oriStr = retStr
			set retStr = $ZSTRIP( retStr, "*W") // Strip all spaces
			set headInd = $FIND(retStr, infoSearchStr) // find first line: Last Changed Rev:
			if ( headInd > 0)
			{
				set endLnInd = $FIND(retStr, "<BR>", headInd) // find end of this line
				set revInd = $FIND(retStr, infoSearchStr _ rev) // find line with specified SVN rev number

				if ( revInd = 0) // Not found
				{
					// Search SVN log entries
					set logInd = $FIND(retStr, logSearchStr)
					if ( logInd = 0)
					{
						Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, fileType _ " file at Revision number " _ rev _ " is not found")
						set tSC = $$$ERROR($$$GeneralError, fileType _ ", Revision number " _ rev _ " is not a valid checked-in version, " _ $EXTRACT(retStr, headInd - $L(infoSearchStr), endLnInd -1) )
						Quit 
					}
					else // found the revision
					{
						Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Revision number " _ rev _ " is not the last checked-in version. " _ logSearchStr)
						set tSC = $$$ERROR($$$GeneralError, fileType _ ", Revision number " _ rev _ " is an old checked-in version, " _ $EXTRACT(retStr, headInd - $L(infoSearchStr), endLnInd -1))
						Quit 

					}
				}
				elseif ((headInd - $L(infoSearchStr)) '= (revInd - $L(infoSearchStr _ rev))) // Verify that both lines have same start index
				{
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Revision number " _ rev _ " is not the last checked-in version. <BR>" _ $EXTRACT(retStr, headInd - $L(infoSearchStr), endLnInd -1))
					set tSC = $$$ERROR($$$GeneralError, fileType _ ", Revision number " _ rev _ " is a old checked-in version. <BR>" _ $EXTRACT(retStr, headInd - $L(infoSearchStr), endLnInd -1))
					Quit 
				}
				else
				{
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "Last checked in Revision number found: " _  rev)
				}
			}
			else
			{
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, fileType _ ", Fatal Error: " _ oriStr)
					set tSC = $$$ERROR($$$GeneralError, "Fatal Error: " _ oriStr)
					Quit 

			}
		}
	}
	Quit tSC
